	teamID := ctx.PathParamInt64("teamid")
	isTeamMember, err := organization.IsUserInTeams(ctx, u.ID, []int64{teamID})
	if err != nil {
		ctx.APIErrorInternal(err)
		return
	} else if !isTeamMember {
		ctx.APIErrorNotFound()
